/// <reference types="vite/client" />

/** Set by `define` in vite.config.ts; shown in Settings > About. */
declare const __APP_VERSION__: string;
/** Full commit hash the build was made from, or "" when unknown. */
declare const __APP_COMMIT__: string;
/** ISO date of that commit, or "" when the build had no git history. */
declare const __APP_COMMIT_DATE__: string;
/** ISO date of the build. */
declare const __APP_BUILT__: string;
